contract InvMutTest {
    C c;

    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint256 value) public {
        uint256 senderBefore = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 zeroBefore = c.balanceOf(address(0)); if (__ESBMC_reverted()) return;
        uint256 totalBefore = c.totalSupply(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.transfer(address(0), value); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(reverted && c.balanceOf(address(this)) == senderBefore && c.balanceOf(address(0)) == zeroBefore && c.totalSupply() == totalBefore);
    }
}

