contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ERCDDAToken c;

    function setUp() public {
        c = new ERCDDAToken(0, "", "");
    }

    function _run(uint256 value) internal {
        uint256 senderBefore;
        try c.balanceOf(address(this)) returns (uint256 __r) { senderBefore = __r; } catch { return; }
        uint256 zeroBefore;
        try c.balanceOf(address(0)) returns (uint256 __r) { zeroBefore = __r; } catch { return; }
        uint256 totalBefore;
        try c.totalSupply() returns (uint256 __r) { totalBefore = __r; } catch { return; }
        bool reverted;
        try c.transfer(address(0), value) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted && c.balanceOf(address(this)) == senderBefore && c.balanceOf(address(0)) == zeroBefore && c.totalSupply() == totalBefore);
    }

    function testFuzz_run(uint256 value) public {
        _run(value);
    }

    receive() external payable {}
}
